        "loadingTipLabel": "DICA",
        "loadingTip1": "Edite animações existentes: Abra um bootanimation.zip e continue trabalhando nas partes, frames e áudio.",
        "loadingTip2": "Módulo companion: O Studio funciona sem root; o módulo opcional adiciona instalação direta, histórico, pull e teste no celular.",
        "loadingTip3": "Mantenha o boot leve: Resolução, FPS e qualidade maiores podem deixar a inicialização mais pesada e aumentar bastante o arquivo.",
        "loadingTip4": "Smart Optimize: Deixe o Studio testar combinações mais leves quando quiser equilibrar melhor qualidade e tamanho.",
        "loadingTip5": "Escolha o enquadramento: Preencher corta as bordas, Ajustar mantém o quadro inteiro e Esticar altera a proporção para preencher a tela.",
        "loadingTip6": "Escolha um bom frame de referência: A prévia de enquadramento pode usar um ponto independente do marcador principal da edição.",
        "loadingTip7": "Vá além de três trechos: Partes Avançadas permite montar sequências com quantas partes a animação precisar.",
        "loadingTip8": "Entenda p e c: p pode ser interrompido quando o Android termina de iniciar, enquanto c reproduz a parte até o fim.",
        "loadingTip9": "Segure uma Parte: Pressione um card de Parte para definir rapidamente o início ou o fim usando a posição atual da timeline.",
        "loadingTip10": "O áudio acompanha a estrutura: Cada trecho ou Parte Avançada pode usar o áudio do vídeo, um arquivo externo ou nenhum áudio.",
        "loadingTip11": "Veja a prévia antes de gerar: Confira enquadramento e limites dos trechos antes de criar o pacote final.",
        "loadingTip12": "Conectado não significa instalação obrigatória: Você pode manter o celular pareado e ainda baixar o arquivo final normalmente.",
        "loadingTip13": "Módulo root para compartilhar: Você pode gerar um módulo root independente mesmo com o seu celular conectado.",
        "loadingTip14": "Use o histórico do celular: O companion guarda animações recentes para você restaurar uma versão anterior rapidamente.",
        "loadingTip15": "Teste sem reiniciar: Em configurações compatíveis, o companion consegue mostrar a boot animation no celular sem um reboot completo.",
        "loadingTip16": "Faça o loop parecer contínuo: Escolha pontos visualmente parecidos no início e no fim do loop para esconder a transição.",
        "loadingTip17": "JPEG ou PNG: JPEG costuma gerar arquivos menores; PNG preserva detalhes mais nítidos e evita artefatos de compressão JPEG.",
        "loadingTip18": "Abra direto do celular: O companion pode puxar para o editor a animação customizada instalada ou a animação original do sistema.",
        "loadingTip19": "Misture fontes: Partes Avançadas podem usar vídeos, GIFs ou imagens diferentes dentro do mesmo projeto de boot animation.",
