        "loadingTip1": "Bestehende Animationen bearbeiten: Öffne eine bootanimation.zip und arbeite weiter an Parts, Frames und Audio.",
        "loadingTip2": "Companion-Modul: Das Studio funktioniert ohne Root; das optionale Modul ergänzt direkte Installation, Verlauf, Abruf und Smartphone-Tests.",
        "loadingTip3": "Boot leicht halten: Höhere Auflösung, FPS und Qualität können den Start schwerer machen und die Dateigröße erhöhen.",
        "loadingTip4": "Smart Optimize: Lass das Studio leichtere Kombinationen testen, wenn du Qualität und Größe besser ausbalancieren möchtest.",
        "loadingTip5": "Framing wählen: Fill schneidet Ränder ab, Fit behält den gesamten Frame und Stretch füllt den Bildschirm durch Ändern der Proportionen.",
        "loadingTip6": "Nützlichen Crop-Frame wählen: Die Framing-Vorschau kann einen Referenzpunkt verwenden, der unabhängig vom Bearbeitungs-Abspielkopf ist.",
        "loadingTip7": "Mehr als drei Abschnitte: Mit Advanced Parts kannst du Sequenzen mit so vielen Parts erstellen, wie deine Animation braucht.",
        "loadingTip8": "p und c verstehen: p kann stoppen, wenn Android den Bootvorgang beendet, während c den Part vollständig abspielt.",
        "loadingTip9": "Part lange drücken: Halte eine Part-Karte gedrückt, um Start oder Ende schnell auf die aktuelle Timeline-Position zu setzen.",
        "loadingTip10": "Audio kann der Struktur folgen: Jeder Abschnitt oder Advanced Part kann Video-Audio, eine externe Datei oder kein Audio verwenden.",
        "loadingTip11": "Vorschau vor dem Build: Prüfe Framing und Abschnittsgrenzen, bevor du das finale Paket generierst.",
        "loadingTip12": "Verbunden heißt nicht Zwangsinstallation: Du kannst das Smartphone gekoppelt lassen und die fertige Datei trotzdem herunterladen.",
        "loadingTip13": "Teilbares Root-Paket: Du kannst ein eigenständiges Root-Modul erzeugen, auch wenn dein eigenes Smartphone verbunden ist.",
        "loadingTip14": "Geräteverlauf nutzen: Der Companion behält aktuelle Animationen, damit du schnell eine frühere Version wiederherstellen kannst.",
        "loadingTip15": "Ohne Neustart testen: Auf kompatiblen Setups kann der Companion die Bootanimation auf dem Smartphone ohne vollständigen Neustart anzeigen.",
