        "loadingTip1": "Modifica animazioni esistenti: apri una bootanimation.zip e continua a lavorare su Parts, fotogrammi e audio.",
        "loadingTip2": "Modulo Companion: lo Studio funziona senza root; il modulo opzionale aggiunge installazione diretta, Cronologia, estrazione e test sul telefono.",
        "loadingTip3": "Mantieni leggero l'avvio: risoluzione, FPS e qualità maggiori possono rendere l'avvio più pesante e aumentare la dimensione del file.",
        "loadingTip4": "Smart Optimize: lascia che lo Studio provi combinazioni più leggere per bilanciare meglio qualità e dimensioni.",
        "loadingTip5": "Scegli l'inquadratura: Fill ritaglia i bordi, Fit mantiene tutto il fotogramma e Stretch riempie lo schermo cambiando le proporzioni.",
        "loadingTip6": "Scegli un fotogramma di ritaglio utile: l'anteprima Inquadratura può usare un punto di riferimento indipendente dalla testina di modifica.",
        "loadingTip7": "Oltre tre sezioni: Advanced Parts permette sequenze con tutte le Parts necessarie.",
        "loadingTip8": "Conosci p e c: p può interrompersi quando Android termina l'avvio, mentre c riproduce la Part fino alla fine.",
        "loadingTip9": "Pressione lunga su una Part: tieni premuta la scheda Part per impostare rapidamente inizio o fine alla posizione corrente della timeline.",
        "loadingTip10": "L'audio può seguire la struttura: ogni sezione o Advanced Part può usare audio video, un file esterno o nessun audio.",
        "loadingTip11": "Anteprima prima della build: controlla inquadratura e confini delle sezioni prima di generare il pacchetto finale.",
        "loadingTip12": "Connesso non significa installazione obbligatoria: puoi lasciare il telefono associato e scaricare comunque il file finito.",
        "loadingTip13": "Pacchetto root condivisibile: puoi generare un modulo root autonomo anche con il tuo telefono connesso.",
        "loadingTip14": "Usa la Cronologia del dispositivo: il Companion conserva le animazioni recenti per ripristinare rapidamente una versione precedente.",
        "loadingTip15": "Prova senza riavviare: su configurazioni compatibili il Companion può mostrare l'animazione di avvio sul telefono senza riavvio completo.",
        "loadingTip16": "Rendi fluidi i loop: scegli punti visivamente simili all'inizio e alla fine del loop per nascondere la transizione.",
        "loadingTip17": "JPEG o PNG: JPEG è solitamente più piccolo, mentre PNG mantiene dettagli più nitidi ed evita artefatti di compressione JPEG.",
