        "loadingTip1": "既存アニメーションを編集: bootanimation.zipを開いてParts、フレーム、音声を編集できます。",
        "loadingTip2": "Companionモジュール: Studioはrootなしでも動作します。任意モジュールで直接インストール、履歴、取得、スマートフォンテストが追加されます。",
        "loadingTip3": "ブートを軽く: 解像度、FPS、品質を上げると起動負荷とファイルサイズが増えます。",
        "loadingTip4": "Smart Optimize: 品質とサイズのバランスを改善したいときに、Studioが軽量な組み合わせをテストします。",
        "loadingTip5": "Framingを選択: Fillは端をクロップ、Fitは全体を保持、Stretchは比率を変えて画面を埋めます。",
        "loadingTip6": "有用なクロップフレームを選択: Framingプレビューでは編集再生ヘッドとは独立した参照点を使用できます。",
        "loadingTip7": "3セクションを超えて: Advanced Partsなら必要な数のPartsでシーケンスを作成できます。",
        "loadingTip8": "pとcを理解: pはAndroid起動完了時に停止する場合があり、cはPartを最後まで再生します。",
        "loadingTip9": "Partを長押し: Partカードを長押しすると開始または終了を現在のタイムライン位置へ素早く設定できます。",
        "loadingTip10": "音声も構造に連動: 各セクションやAdvanced Partで動画音声、外部ファイル、音声なしを選べます。",
        "loadingTip11": "ビルド前にプレビュー: 最終パッケージ生成前にFramingとセクション境界を確認してください。",
        "loadingTip12": "接続済みでも強制インストールではありません: スマートフォンを接続したまま完成ファイルをダウンロードできます。",
        "loadingTip13": "共有可能なrootパッケージ: 自分のスマートフォンが接続中でも単体rootモジュールを生成できます。",
        "loadingTip14": "デバイス履歴を活用: Companionは最近のアニメーションを保持し、以前のバージョンへ素早く戻せます。",
        "loadingTip15": "再起動せずにテスト: 対応環境ではCompanionが完全再起動なしでブートアニメーションを表示できます。",
        "loadingTip16": "シームレスなループ: ループ開始と終了で見た目が似た点を選ぶと切り替わりを隠せます。",
        "loadingTip17": "JPEGかPNG: JPEGは通常小さく、PNGはより鮮明なディテールを保持しJPEG圧縮アーティファクトを避けます。",
        "loadingTip18": "スマートフォンから開く: Companionはインストール済みカスタムアニメーションまたは元のシステムアニメーションをエディターへ取得できます。",
        "loadingTip19": "ソースを混在: Advanced Partsでは同じブートアニメーションプロジェクト内で異なる動画、GIF、画像を使用できます。",
